import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def generate_candidates(limit):
    candidates = set()

    # Max d^2 should be around limit/5 (since smallest K=5)
    max_d = int(math.sqrt(limit / 5)) + 1

    for d in range(2, max_d + 1):
        d_squared = d * d

        # Iterate through a and b such that a < b and gcd(a, b) = 1
        # Estimate maximum possible b: d^2(a^2 + b^2) < limit => b^2 < limit/d^2
        # Since a >= 1, b^2 < limit/d^2 - 1
        max_b_approx = int(math.sqrt(limit / d_squared)) + 1

        for a in range(1, max_b_approx // 2 + 1):
            for b in range(a + 1, max_b_approx + 1):
                if gcd(a, b) == 1:
                    K = a*a + b*b
                    m = d_squared * K
                    if m < limit:
                        candidates.add(m)
                    else:
                        # Since we fix d, K is increasing with b, we can break inner loop
                        # But since we are using approximation for max_b, we keep it simple.
                        pass

    return sorted(list(candidates))

# We are looking for the 20th smallest, so we search up to a limit slightly above the expected 234. Let's use 300.
LIMIT = 300
sorted_candidates = generate_candidates(LIMIT)

print(f"Total candidates found below {LIMIT}: {len(sorted_candidates)}")
print("Top 25 candidates:")
for i, m in enumerate(sorted_candidates[:25]):
    print(f"{i+1}. {m}")

print(f"\n20th smallest candidate: {sorted_candidates[19]}")

