def generate_good_numbers_gcd_gt_1(limit=30):
    """Generates good numbers m = x^2 + y^2 where gcd(x, y) > 1 and x < y."""
    numbers = set()
    for x in range(1, limit + 1):
        for y in range(x + 1, limit + 1):
            if gcd(x, y) > 1:
                m = x**2 + y**2
                numbers.add(m)
    return sorted(list(numbers))

# Generate and print the list
list_of_numbers = generate_good_numbers_gcd_gt_1()
