import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

good_numbers = set()
limit_y = 32  # Since 31^2 < 1000 and 32^2 > 1000, this covers the range.

for y in range(2, limit_y):
    for x in range(1, y):
        if gcd(x, y) > 1:
            m = x**2 + y**2
            if m < 1000:
                good_numbers.add(m)

# Sort the distinct good numbers
sorted_good_numbers = sorted(list(good_numbers))

# List at least 30, or all if less than 30
output = sorted_good_numbers[:30]

print(f"Total distinct good numbers found under 1000: {len(sorted_good_numbers)}")
print("List of the first 30 good numbers (m = x^2 + y^2, gcd(x,y) > 1):")
print(output)

# Calculate the sequence S_x = x^2 + (x+1)^2 for x=1 to 30
results = {}
for x in range(1, 31):
    s_x = x**2 + (x + 1)**2
    results[x] = s_x

# Print the results formatted
print("X\tS_x")
for x, s_x in results.items():
    print(f"{x}\t{s_x}")

